    1→/**
    2→ * DRM 图片加密器
    3→ * 使用 AES-GCM 对图片数据进行加密和解密
    4→ */
    5→class DRMEncryptor {
    6→    constructor() {
    7→        this.algo = 'AES-GCM';
    8→        this.version = '1.0';
    9→    }
   10→
   11→    /**
   12→     * 生成随机密钥（256 位）
   13→     * @returns {string} Base64 编码的密钥
   14→     */
   15→    generateKey() {
   16→        const array = new Uint8Array(32); // 256 位 = 32 字节
   17→        window.crypto.getRandomValues(array);
   18→        return btoa(String.fromCharCode(...Array.from(array)));
   19→    }
   20→
   21→    /**
   22→     * 生成随机 IV（12 字节）
   23→     * @returns {string} Base64 编码的 IV
   24→     */
   25→    generateIV() {
   26→        const array = new Uint8Array(12); // GCM 模式需要 12 字节 IV
   27→        window.crypto.getRandomValues(array);
   28→        return btoa(String.fromCharCode(...Array.from(array)));
   29→    }
   30→
   31→    /**
   32→     * 加密图片数据
   33→     * @param {string} imageData - Base64 编码的图片数据
   34→     * @param {string} keyBase64 - Base64 编码的密钥
   35→     * @returns {Promise} 加密结果
   36→     */
   37→    async encrypt(imageData, keyBase64) {
   38→        try {
   39→            const key = this.base64ToKey(keyBase64);
   40→            const iv = this.generateIV();
   41→            
   42→            // 解码图片数据
   43→            const imageBytes = await this.base64ToArrayBuffer(imageData);
   44→            
   45→            // 加密
   46→            const encrypted = await window.crypto.subtle.encrypt(
   47→                { name: this.algo, iv: this.arrayBufferToUint8Array(iv) },
   48→                key,
   49→                imageBytes
   50→            );
   51→            
   52→            return {
   53→                encryptedData: btoa(String.fromCharCode(...Array.from(new Uint8Array(encrypted)))),
   54→                iv: iv,
   55→                timestamp: Date.now(),
   56→                version: this.version
   57→            };
   58→        } catch (error) {
   59→            console.error('加密错误:', error);
   60→            throw error;
   61→        }
   62→    }
   63→
   64→    /**
   65→     * 解密图片数据
   66→     * @param {string} encryptedDataBase64 - Base64 编码的加密数据
   67→     * @param {string} keyBase64 - Base64 编码的密钥
   68→     * @param {string} ivBase64 - Base64 编码的 IV
   69→     * @returns {Promise} 解密结果
   70→     */
   71→    async decrypt(encryptedDataBase64, keyBase64, ivBase64) {
   72→        try {
   73→            const key = this.base64ToKey(keyBase64);
   74→            const iv = this.arrayBufferToUint8Array(this.base64ToArrayBuffer(ivBase64));
   75→            
   76→            // 解码加密数据
   77→            const encryptedBytes = await this.base64ToArrayBuffer(encryptedDataBase64);
   78→            
   79→            // 解密
   80→            const decrypted = await window.crypto.subtle.decrypt(
   81→                { name: this.algo, iv },
   82→                key,
   83→                encryptedBytes
   84→            );
   85→            
   86→            return {
   87→                decryptedData: btoa(String.fromCharCode(...Array.from(new Uint8Array(decrypted)))),
   88→                timestamp: Date.now(),
   89→                version: this.version
   90→            };
   91→        } catch (error) {
   92→            console.error('解密错误:', error);
   93→            throw error;
   94→        }
   95→    }
   96→
   97→    /**
   98→     * Base64 字符串转密钥 ArrayBuffer
   99→     */
  100→    base64ToKey(base64) {
  101→        const binaryString = atob(base64);
  102→        const bytes = new Uint8Array(binaryString.length);
  103→        for (let i = 0; i < binaryString.length; i++) {
  104→            bytes[i] = binaryString.charCodeAt(i);
  105→        }
  106→        return bytes.buffer;
  107→    }
  108→
  109→    /**
  110→     * ArrayBuffer 转 Uint8Array
  111→     */
  112→    arrayBufferToUint8Array(arrayBuffer) {
  113→        const uint8 = new Uint8Array(arrayBuffer);
  114→        return uint8;
  115→    }
  116→
  117→    /**
  118→     * Base64 字符串转 ArrayBuffer
  119→     */
  120→    async base64ToArrayBuffer(base64) {
  121→        const binaryString = atob(base64);
  122→        const bytes = new Uint8Array(binaryString.length);
  123→        for (let i = 0; i < binaryString.length; i++) {
  124→            bytes[i] = binaryString.charCodeAt(i);
  125→        }
  126→        return bytes.buffer;
  127→    }
  128→}
  129→
  130→// 全局实例
  131→window.DRMEncryptor = DRMEncryptor;

